                else {
                    $(".rec").attr("onclick", "SetRecommand('T', '" + pCNTN_CD + "')");
                    $(".rec").removeClass("on");
                    $(".rec").find(".number").html(pStr.split('|')[1]);
                }
            }
            else {
                alert(pStr);
            }
        }
